//! Outbound housing GameEvent parity against verbatim ACE writers.
//! `tests/fixtures/housing_output.csv` is generated by `oracle/housing_output_generate.py`.
//! Each `output,<name>,<hex>` row is the ACE GameEvent message for the scenario below.
use bace_wire::{
    HAR_ALLEGIANCE_GUESTS, HAR_OPEN_HOUSE, HOUSE_BITFIELD_ACTIVE, HOUSE_RECORD_VERSION,
    HouseAccess, HouseData, HouseGuest, HousePayment, HouseProfile, HouseType, HousingEvent,
    HousingLimits, RestrictionDb, WeenieError, WireError, WirePosition,
};

const FIXTURE: &str = include_str!("fixtures/housing_output.csv");
/// Harness session: player object 0x50000001, game-event sequence 0x2A.
const OBJECT: u32 = 0x5000_0001;
/// Sequence of the first fixture row; later rows follow in order.
const SEQUENCE: u32 = 0x2A;
const EXPECTED_ROWS: usize = 12;

const BUY: &[HousePayment<'static>] = &[
    HousePayment {
        num: 2,
        paid: 1,
        weenie_id: 273,
        name: "Pyreal",
        plural_name: "Pyreals",
    },
    HousePayment {
        num: 1,
        paid: 0,
        weenie_id: 0x9000,
        name: "Key",
        plural_name: "Keys",
    },
];
const RENT: &[HousePayment<'static>] = &[HousePayment {
    num: 5,
    paid: 5,
    weenie_id: 273,
    name: "Pyreal",
    plural_name: "Pyreals",
}];
const COIN: &[HousePayment<'static>] = &[HousePayment {
    num: 1,
    paid: 0,
    weenie_id: 1,
    name: "Coin",
    plural_name: "Coins",
}];
const GUESTS: &[HouseGuest<'static>] = &[
    HouseGuest {
        id: 0x5000_0001,
        item_storage: false,
        name: "Alpha",
    },
    HouseGuest {
        id: 0x5000_0041,
        item_storage: true,
        name: "Bravo",
    },
    HouseGuest {
        id: 0x5000_0002,
        item_storage: false,
        name: "Charlie",
    },
];
const ROOMMATES: &[u32] = &[0x5000_0003, 0x5000_0004];
const RESTRICTIONS: &[(u32, u32)] = &[
    (0x5000_0001, 0),
    (0x5000_0041, 1),
    (0x5000_0002, 1),
    (0x5000_0007, 0),
];
const LOCATIONS: &[u32] = &[0x7000_0001, 0x7000_0002];

fn limits() -> HousingLimits {
    HousingLimits {
        max_message_bytes: 4096,
        max_string_bytes: 64,
        max_entries: 16,
    }
}

fn bytes(hex: &str) -> Vec<u8> {
    (0..hex.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).expect("fixture hex"))
        .collect()
}

fn scenario(name: &str) -> Option<HousingEvent<'static>> {
    Some(match name {
        "profile" => HousingEvent::Profile {
            crystal: 0x7000_0001,
            profile: HouseProfile {
                dwelling_id: 0x1234,
                owner_id: 0x5000_0002,
                bitmask: HOUSE_BITFIELD_ACTIVE,
                min_level: -1,
                max_level: 50,
                min_allegiance_rank: -1,
                max_allegiance_rank: 3,
                maintenance_free: true,
                house_type: HouseType::Villa,
                owner_name: "Caf\u{e9}",
                buy: BUY,
                rent: RENT,
            },
        },
        "profile_empty" => HousingEvent::Profile {
            crystal: 0x7000_0002,
            profile: HouseProfile {
                bitmask: 2,
                ..profile_base()
            },
        },
        "data" => HousingEvent::Data(HouseData {
            buy_time: 1000,
            rent_time: 2000,
            house_type: HouseType::Cottage,
            maintenance_free: false,
            buy: COIN,
            rent: &[],
            position: WirePosition {
                cell: 0x1234_0001,
                origin: [1.5, -2.25, 3.0],
                rotation: [1.0, 0.5, 0.25, 0.0],
            },
        }),
        "access" => HousingEvent::AccessList(HouseAccess {
            version: HOUSE_RECORD_VERSION,
            bitmask: HAR_OPEN_HOUSE | HAR_ALLEGIANCE_GUESTS,
            monarch_id: 0x5000_0009,
            guests: GUESTS,
            roommates: ROOMMATES,
        }),
        "access_empty" => HousingEvent::AccessList(HouseAccess {
            version: HOUSE_RECORD_VERSION,
            bitmask: 0,
            monarch_id: 0,
            guests: &[],
            roommates: &[],
        }),
        "status_default" => HousingEvent::Status(WeenieError::BadParam),
        "status_nomem" => HousingEvent::Status(WeenieError::NoMem),
        "rent_time" => HousingEvent::RentTime(0),
        "rent_payments" => HousingEvent::RentPayments(&[]),
        "transaction" => HousingEvent::Transaction,
        "restrictions" => HousingEvent::Restrictions {
            sequence: 0x11,
            object: 0x7000_0003,
            db: RestrictionDb {
                version: HOUSE_RECORD_VERSION,
                open_status: false,
                monarch_id: 0x5000_0009,
                table: RESTRICTIONS,
            },
        },
        "available" => HousingEvent::AvailableHouses {
            house_type: HouseType::Mansion,
            locations: LOCATIONS,
            total_available: 9,
        },
        _ => return None,
    })
}

fn output_rows() -> Vec<(&'static str, &'static str)> {
    FIXTURE
        .lines()
        .filter_map(|line| line.strip_prefix("output,"))
        .map(|row| row.split_once(',').expect("output row has a name and hex"))
        .collect()
}

#[test]
fn housing_events_match_verbatim_ace_vectors() {
    let rows = output_rows();
    assert_eq!(rows.len(), EXPECTED_ROWS);
    // The harness session increments its game-event sequence once per message, in row order.
    for (index, (name, hex)) in rows.into_iter().enumerate() {
        let event = scenario(name).unwrap_or_else(|| panic!("no scenario for {name}"));
        let sequence = SEQUENCE + index as u32;
        let encoded = event
            .encode(OBJECT, sequence, limits())
            .unwrap_or_else(|error| panic!("{name} failed: {error:?}"));
        assert_eq!(encoded, bytes(hex), "{name}");
    }
}

#[test]
fn guest_order_does_not_change_the_hash_table_bytes() {
    let reversed: Vec<HouseGuest<'_>> = GUESTS.iter().rev().copied().collect();
    let forward = HousingEvent::AccessList(HouseAccess {
        version: HOUSE_RECORD_VERSION,
        bitmask: HAR_OPEN_HOUSE | HAR_ALLEGIANCE_GUESTS,
        monarch_id: 0x5000_0009,
        guests: GUESTS,
        roommates: ROOMMATES,
    });
    let backward = HousingEvent::AccessList(HouseAccess {
        version: HOUSE_RECORD_VERSION,
        bitmask: HAR_OPEN_HOUSE | HAR_ALLEGIANCE_GUESTS,
        monarch_id: 0x5000_0009,
        guests: &reversed,
        roommates: ROOMMATES,
    });
    assert_eq!(
        forward.encode(OBJECT, SEQUENCE, limits()),
        backward.encode(OBJECT, SEQUENCE, limits())
    );
}

#[test]
fn housing_lists_strings_and_messages_fail_closed() {
    let small = HousingLimits {
        max_entries: 2,
        ..limits()
    };
    let access = |guests: &'static [HouseGuest<'static>]| {
        HousingEvent::AccessList(HouseAccess {
            version: HOUSE_RECORD_VERSION,
            bitmask: 0,
            monarch_id: 0,
            guests,
            roommates: &[],
        })
    };
    assert_eq!(
        access(GUESTS).encode(OBJECT, SEQUENCE, small),
        Err(WireError::LimitExceeded),
        "three guests exceed max_entries 2"
    );
    const DUPLICATE: &[HouseGuest<'static>] = &[
        HouseGuest {
            id: 0x5000_0001,
            item_storage: false,
            name: "A",
        },
        HouseGuest {
            id: 0x5000_0001,
            item_storage: true,
            name: "B",
        },
    ];
    assert_eq!(
        access(DUPLICATE).encode(OBJECT, SEQUENCE, limits()),
        Err(WireError::InvalidEncoding),
        "duplicate guest IDs"
    );

    let at_limit = "\u{e9}".repeat(64);
    let over_limit = "\u{e9}".repeat(65);
    assert!(
        owner_named(&at_limit)
            .encode(OBJECT, SEQUENCE, limits())
            .is_ok()
    );
    assert_eq!(
        owner_named(&over_limit).encode(OBJECT, SEQUENCE, limits()),
        Err(WireError::LimitExceeded),
        "65 Windows-1252 bytes exceed max_string_bytes 64"
    );
    assert_eq!(
        owner_named("\u{4e2d}").encode(OBJECT, SEQUENCE, limits()),
        Err(WireError::InvalidEncoding),
        "non-Windows-1252 text is rejected, not substituted"
    );

    let tight = HousingLimits {
        max_message_bytes: 40,
        ..limits()
    };
    assert_eq!(
        scenario("profile").unwrap().encode(OBJECT, SEQUENCE, tight),
        Err(WireError::LimitExceeded)
    );

    let locations: &'static [u32] = &[1, 2, 3];
    assert_eq!(
        HousingEvent::AvailableHouses {
            house_type: HouseType::Villa,
            locations,
            total_available: 3,
        }
        .encode(OBJECT, SEQUENCE, small),
        Err(WireError::LimitExceeded)
    );

    const TOO_MANY_PAYMENTS: &[HousePayment<'static>] = &[HousePayment {
        num: 1,
        paid: 0,
        weenie_id: 1,
        name: "a",
        plural_name: "a",
    }; 3];
    assert_eq!(
        HousingEvent::RentPayments(TOO_MANY_PAYMENTS).encode(OBJECT, SEQUENCE, small),
        Err(WireError::LimitExceeded)
    );

    const DUPLICATE_RESTRICTION: &[(u32, u32)] = &[(0x5000_0001, 0), (0x5000_0001, 1)];
    assert_eq!(
        HousingEvent::Restrictions {
            sequence: 0,
            object: 1,
            db: RestrictionDb {
                version: HOUSE_RECORD_VERSION,
                open_status: false,
                monarch_id: 0,
                table: DUPLICATE_RESTRICTION,
            },
        }
        .encode(OBJECT, SEQUENCE, limits()),
        Err(WireError::InvalidEncoding)
    );
}

fn profile_base() -> HouseProfile<'static> {
    HouseProfile {
        dwelling_id: 0,
        owner_id: 0,
        bitmask: 0,
        min_level: -1,
        max_level: -1,
        min_allegiance_rank: -1,
        max_allegiance_rank: -1,
        maintenance_free: false,
        house_type: HouseType::Undef,
        owner_name: "",
        buy: &[],
        rent: &[],
    }
}

fn owner_named(name: &str) -> HousingEvent<'_> {
    HousingEvent::Profile {
        crystal: 1,
        profile: HouseProfile {
            owner_name: name,
            ..profile_base()
        },
    }
}
